Here is a complete, production-ready example of an `onSubmit` function for a React form that sends data to a GraphQL API.

This example uses **React Hook Form** (industry standard for complex forms) and **Apollo Client** (the standard for GraphQL state management).

### The `onSubmit` Function

```javascript
import { useMutation } from '@apollo/client';
import { toast } from 'react-toastify'; // Optional: for user feedback

// 1. Define the GraphQL Mutation
const CREATE_USER_MUTATION = `
  mutation CreateUser($input: CreateUserInput!) {
    createUser(input: $input) {
      id
      email
      createdAt
    }
  }
`;

export const useCreateUser = () => {
  // 2. Initialize the mutation hook
  const [createUser, { loading, error }] = useMutation(CREATE_USER_MUTATION, {
    // Optional: Handle errors globally or per mutation
    onError: (err) => {
      console.error('Mutation failed:', err);
      toast.error('Failed to create user. Please try again.');
    },
  });

  // 3. The onSubmit function
  const handleSubmit = async (data) => {
    try {
      // Check if loading to prevent double submission
      if (loading) return;

      // 4. Execute the mutation with variables
      const { data: mutationData } = await createUser({
        variables: {
          input: {
            // Map your form data to the GraphQL schema
            email: data.email,
            name: data.name,
            // ... other fields
          },
        },
      });

      // 5. Handle success
      console.log('User created:', mutationData.createUser);
      toast.success('User created successfully!');

      // Reset form or redirect
      // window.location.href = '/dashboard';
    } catch (err) {
      console.error('Unexpected error:', err);
      toast.error('An unexpected error occurred.');
    }
  };

  return { handleSubmit, loading, error };
};
```

