### Step 1: Create the Worker File

Create a file named `csv-worker.js` in your `app` directory. This file will run in the background thread.

**`app/worker/csv-worker.js`**

```javascript
// app/worker/csv-worker.js

// Simple CSV Parser (handles basic commas, no complex quoting for brevity)
// In production, consider using a library like PapaParse inside the worker
export function parseCSV(csvText) {
  const lines = csvText.split(/\r\n|\n/);
  const headers = lines[0].split(',').map(h => h.trim());
  const data = [];

  for (let i = 1; i < lines.length; i++) {
    const currentLine = lines[i].split(',').map(cell => cell.trim());
    const row = {};
    headers.forEach((header, index) => {
      row[header] = currentLine[index] || '';
    });
    data.push(row);
  }

  return data;
}

// The Worker Message Handler
self.onmessage = function(e) {
  const { type, payload } = e.data;

  if (type === 'PARSE_CSV') {
    try {
      const result = parseCSV(payload);
      self.postMessage({ type: 'PARSE_RESULT', payload: result });
    } catch (error) {
      self.postMessage({ type: 'PARSE_ERROR', payload: error.message });
    }
  }
};
```

