### 1. The Backend (`server.js`)

This server handles the WebSocket connections and creates a "Peer" for every user.

```javascript
const express = require('express');
const http = require('http');
const { Server } = require('socket.io');
const Peer = require('peerjs');

const app = express();
const server = http.createServer(app);
const io = new Server(server);

// Serve static files (HTML/CSS/JS)
app.use(express.static('public'));

// Store active peers
const peers = {};

io.on('connection', (socket) => {
    console.log('User connected:', socket.id);

    // Create a Peer for this user
    const peer = new Peer();

    peer.on('open', (id) => {
        console.log('My Peer ID:', id);
        peers[socket.id] = { peer, socket };

        // Send my ID to the user so they can connect to me
        socket.emit('my-id', id);
    });

    peer.on('connection', (conn) => {
        // When someone connects to me
        const { socketId } = conn.metadata;
        const targetSocket = io.sockets.sockets.get(socketId);

        if (targetSocket) {
            // Send the new peer's ID to the target user
            targetSocket.emit('peer-connected', conn.peer);

            // Send the target's ID to me so I can send video to them
            conn.on('data', (data) => {
                targetSocket.emit('data', data);
            });
        }
    });

    socket.on('disconnect', () => {
        console.log('User disconnected');
        if (peers[socket.id]) {
            peers[socket.id].peer.destroy();
            delete peers[socket.id];
        }
    });
});

const PORT = 3000;
server.listen(PORT, () => {
    console.log(`Server running on http://localhost:${PORT}`);
});
```

