```javascript
// server.js
require('dotenv').config();
const express = require('express');
const { Pool } = require('pg');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

// Database Connection
const pool = new Pool({
  connectionString: process.env.DATABASE_URL || 'postgres://localhost:5432/hotel_db'
});

// Autocomplete Endpoint
app.get('/api/hotels', async (req, res) => {
  const { query } = req.query;

  if (!query || query.length < 2) {
    return res.status(400).json({ error: 'Query must be at least 2 characters' });
  }

  try {
    // SQL Query with ILIKE for case-insensitive partial matching
    // We use a subquery to ensure we only get hotels where the name starts with the query
    const queryText = `
      SELECT id, name, city, country, rating
      FROM hotels
      WHERE name ILIKE $1
      ORDER BY name ASC
      LIMIT 10
    `;

    const values = [`%${query}%`]; // Postgres parameterized query to prevent SQL injection

    const result = await pool.query(queryText, values);

    // Transform data to match frontend expectations
    const hotels = result.rows.map(h => ({
      id: h.id,
      name: h.name,
      city: h.city,
      country: h.country,
      rating: h.rating
    }));

    res.json({ results: hotels });

  } catch (error) {
    console.error('Database Error:', error);
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

