```protobuf
syntax = "proto3";

package playbook;

option go_package = "github.com/example/ansible-grpc";

// Request to run a playbook
message RunRequest {
  string playbook_path = 1;
  map<string, string> extra_vars = 2;
}

// Response containing a single line of output
message OutputLine {
  string content = 1;
  bool is_error = 2; // true if stderr
}

// Service definition
service AnsibleService {
  // Unary call to start the stream
  rpc RunPlaybook (RunRequest) returns (stream OutputLine);
}
```

