  myKey: "Hello World",
  myNumber: 123,
  myArray: [1, 2, 3]
});

// 2. 读取数据 (异步)
chrome.storage.local.get(['myKey'], (result) => {
  console.log(result.myKey); 
});

// 3. 删除数据
