public class PolygonRefactoring {
    public static boolean isInside(Polygon polygon, int x, int y) {
        // Create an Area object from the Polygon
        Area area = new Area(polygon);

        // Create a point to check
        java.awt.geom.Point2D.Double point = new java.awt.geom.Point2D.Double(x, y);

        // Check if the point is inside the Area
        return area.contains(point);
    }

